<div class="page-head"><div><h1><?= e(t('rcsa.title')) ?></h1><p class="sub"><?= e(t('rcsa.subtitle')) ?></p></div>
<div class="actions"><?php if (can('rcsa.manage')): ?><a class="btn gold" href="<?= e(url('rcsa/launch')) ?>"><?= e(t('rcsa.launch')) ?></a><a class="btn secondary" href="<?= e(url('rcsa/templates/new')) ?>"><?= e(t('rcsa.template_new')) ?></a><?php endif; ?></div></div>
<form method="get" action="<?= e(url('rcsa')) ?>" class="card filters">
<?= ff('select', 'status', 'rcsa.status', $f['status'], ['options' => opts(['draft', 'submitted', 'approved', 'returned'], fn($x) => t('enum.status.' . $x), null) ?: [], 'blank_label' => 'common.all']) ?>
<?= ff('select', 'department', 'risk.department', $f['department'], ['options' => opts($departments, fn($d) => lname($d)), 'blank_label' => 'common.all']) ?>
<div class="field"><label class="check"><input type="checkbox" name="overdue" value="1"<?= checked($f['overdue']) ?>> <?= e(t('rcsa.overdue_only')) ?></label></div>
<div class="field actions"><button class="btn" type="submit"><?= e(t('common.filter')) ?></button><a class="btn secondary" href="<?= e(url('rcsa')) ?>"><?= e(t('common.reset')) ?></a></div></form>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('rcsa.id')) ?></th><th><?= e(t('rcsa.template')) ?></th><th><?= e(t('risk.department')) ?> / <?= e(t('risk.branch')) ?></th><th><?= e(t('rcsa.assessor')) ?></th><th><?= e(t('rcsa.due_date')) ?></th><th><?= e(t('rcsa.status')) ?></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="6" class="muted"><?= e(t('common.no_results')) ?></td></tr><?php endif; ?>
<?php foreach ($rows as $a): $late = in_array($a['status'], ['draft', 'returned'], true) && $a['due_date'] < date('Y-m-d'); ?><tr><td class="nowrap"><a href="<?= e(url('rcsa/' . $a['id'])) ?>"><?= e($a['code']) ?></a></td><td><?= e($a['t_title']) ?></td><td><?= e(lname($a, 'dept')) ?><?= $a['branch_id'] ? ' / ' . e(lname($a, 'branch')) : '' ?></td><td><?= e($a['assessor_name']) ?></td><td class="nowrap"><?= e($a['due_date']) ?><?= $late ? ' <span class="badge danger">' . e(t('risk.overdue')) . '</span>' : '' ?></td><td><?= status_badge($a['status']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?= pager($total, $page, $per) ?>
<?php if (can('rcsa.manage')): ?><h2 style="margin-top:24px"><?= e(t('rcsa.templates')) ?></h2><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('rcsa.template_title')) ?></th><th class="num"><?= e(t('rcsa.questions')) ?></th><th><?= e(t('common.status')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($templates as $t): ?><tr><td><?= e($t['title']) ?></td><td class="num"><?= (int)$t['n_q'] ?></td><td><?= $t['is_active'] ? '<span class="badge ok">' . e(t('common.active')) . '</span>' : '<span class="badge">' . e(t('common.inactive')) . '</span>' ?></td><td><a class="btn small secondary" href="<?= e(url('rcsa/templates/' . $t['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
